// return the k nearest places within radiusMeters of (lat, lng)
function findNearest(lat, lng, radiusMeters, k) {
  const cell = h3.latLngToCell(lat, lng, 9);   // ~150 m cells
  const candidates = index.get(cell) || [];    // places in the user's own cell
  const ranked = candidates
    .map(p => ({ p, d: euclidean(lat, lng, p.lat, p.lng) }))
    .sort((a, b) => a.d - b.d);
  return ranked.slice(0, k).map(r => r.p);
}
